import{_ as p,c as e,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"卷七（文言）","description":"伊川易传 - 卷七（文言）","frontmatter":{"title":"卷七（文言）","description":"伊川易传 - 卷七（文言）"},"headers":[],"relativePath":"zh/classics/yichuan/008.md","filePath":"zh/classics/yichuan/008.md"}'),t={name:"zh/classics/yichuan/008.md"};function s(h,a,n,l,c,o){return r(),e("div",null,[...a[0]||(a[0]=[i('<h1 id="卷七-文言" tabindex="-1">卷七（文言） <a class="header-anchor" href="#卷七-文言" aria-label="Permalink to “卷七（文言）”">​</a></h1><p>乾文言</p><h3 id="第一段" tabindex="-1">第一段 <a class="header-anchor" href="#第一段" aria-label="Permalink to “第一段”">​</a></h3><p>“元”者，善之长也；“亨”者，嘉之会也；“利”者，义之和也；“贞”者，事之乾也。(2)君子体仁足以长人，嘉会足以合礼，利物足以和义，贞固足以乾事。君子行此四德者，故曰：“乾、元、亨、利、贞。”(3)初九曰：“潜龙勿用。”何谓也？子曰：“龙德而隐者也，不易乎世，不成乎名，遯世无闷，不见是而无闷，乐则行之，忧则违之，确乎其不可拔，潜龙也。”(4)九二曰：“见龙在田，利见大人。”何谓也？子曰：“龙德而正中者也。庸言之信，庸行之谨，闲邪存其诚，善世而不伐，德博而化，《易》曰‘见龙在田，利见大人’。君德也。”(5)九三曰：“君子终日乾乾，夕惕若厉，无咎。”何谓也？子曰：“君子进德修业。忠信所以进德也。修辞立其诚，所以居业也。知至至之，可与几也。知终终之，可与存义也。是故居上位而不骄，在下位而不忧，故乾乾因其时而惕，虽危无咎矣。”(6)九四曰：“或跃在渊，无咎。”何谓也？子曰：“上下无常，非为邪也。进退无恒，非离群也。君子进德修业，欲及时也，故无咎。”(7)九五曰：“飞龙在天，利见大人。”何谓也？子曰：“同声相应，同气相求。水流湿，火就燥。云从龙，风从虎。圣人作而万物覩。本乎天者亲上，本乎地者亲下。则各从其类也。”(8)上九曰：“亢龙有悔。”何谓也？子曰：“贵而无位，高而无民，贤人在下位而无辅，是以动而有悔也。”</p><h3 id="注释" tabindex="-1">注释 <a class="header-anchor" href="#注释" aria-label="Permalink to “注释”">​</a></h3><p>(1)文言：对“文言”二字之义先儒众说不一，一、乾坤为门户，以文说乾坤；二、依文而言其理；三、因卦爻辞为文王所作，故曰“文言”；四、文谓文饰，以乾坤德大，故特文饰以为“文言”；五、单就卦爻辞而推衍之，故曰“文言”，等等。笔者以为当依文言理之说近实。</p><p>(2)元：开始。长：训首，君。亨：古文字有祭祀之义，此训为通。嘉：美。古者婚礼称“嘉”。会：聚合。利，本指铦。“利”从刀主分，分故能裁成事物使各得宜；“利”从禾。禾二月始生，八月而熟，得时之中，如《说文》所言：“利……和然后利，从和省。”故“利”又有中和之义。义：宜。《中庸》：“义者，宜也。”《白虎通德论·情性》：“义者，宜也，断决得中也。”贞：一说为占问，一说为正。乾：树乾。木旁生者为枝，正出者为乾，故“乾”有正之义，因枝叶依乾而立，故“乾”又有本之义。郑注《礼记·月令》“羽箭乾”曰：“乾者，器之本也。”</p><p>(3)仁：凡果核之实有生气者曰“仁”，以仁为木，案李道平、周易集解纂疏》，“仁”有“元”之义，“元”从二从人，“仁”从人从二，故在天为“元”，在人为“仁”。《释名·释形体》：“人，仁也；仁，生物也。”长人：犹君人，即主宰人。利物：一本作“利之”。</p><p>(4)此释《乾》初九之爻辞。龙德：阳刚之德。《乾》卦爻辞以“龙”喻阳。隐：是释“潜”。《乾》初九居下故曰“隐”。易：移。世：世俗。不见是：不为世人所赞同。遯：隐退。闷：烦闷。确：刚强之貌。拔：移。</p><p>(5)此释《乾》九二爻辞。正中；《乾》九二爻居内卦正得中位。庸言：平常的言论。先儒有解“庸”为“中”者，但由下文“善世而不伐”思之。似解“庸”作平庸为妥。闲：防。善世：吴汝纶曰：“此‘善世’即善大，与‘德博’对文。”伐：自夸。化：感化。君德：即阳德，阳为君。</p><p>(6)此释《乾》九三爻辞。进德修业：增进德性修治学业。九三过中，故曰“进德修业”。修，治。知至至之：前“至”为名词，指到达，后“至”为动词，指努力做到。知终终之：前“终”为名词，指终结。后“终”为动词，指善于停止。几：微。《系辞》：“几者，动之微，吉之先见者也。”上位：九三居内卦之上。下位：指九三居外卦之下。</p><p>(7)此释《乾》卦九四爻辞。上下：言爻位。四为阴位，上可以承君，下可以应初，故曰“上下”。邪，邪枉。九四以阳居阴失位故曰“邪”。进退：言爻，九四上进可居五，下退可居三。群：类。此指阳类。《乾》六爻皆阳，故六阳称“群”。</p><p>(8)此释《乾》九五爻辞。同声相应，同气相求：乾坤阴阳各以类相应相求。乾为纯阳，故曰“同声”、“同气”。应，感应。求，追求。云从龙：云，水气。龙，水物。云龙同类，感气相致，故“云从龙”。风从虎：风为震动之气，虎是威猛之兽，虎啸风生，风与虎也同气类，故曰“风从虎”。作：起。覩：见。亲：亲附。</p><p>(9)此释《乾》上九爻辞，与《系辞上》八章同。注见上。</p><h3 id="第二段" tabindex="-1">第二段 <a class="header-anchor" href="#第二段" aria-label="Permalink to “第二段”">​</a></h3><p>“潜龙勿用”，下也；“见龙在田”，时舍也；“终日乾乾”，行事也；“或跃中渊”，自试也；“飞龙在天”，上治也；“亢龙有悔”，穷之灾也；乾元“用九”，天下治也。①“潜龙勿用”，阳气潜藏；“见龙在田”，天下文明；“终日乾乾”，与时偕行；“或跃在渊”，乾道乃革；“飞龙在天”，乃位乎天德；“亢龙有悔”，与时偕极；乾元“用九”，乃现天则。②乾“元”者，始而亨者也；“利贞”者，性情也。乾始能以美利利天下，不言所利，大矣哉，大哉乾乎，刚健中正，纯粹精也。六爻发挥，旁通情也，时乘六龙，以御天也。云行雨施，天下平也。③君子以成德为行，日可见之行也。“潜”之为言也，隐而未见，行而未成，是以君子弗用也。④君子学以聚之，问以辩之，宽以居之，仁以行之。《易》曰：“见龙在田，利见大人。”君德也。⑤九三重刚而不中，上不在天，下不在田，故乾乾因其时而惕，虽危“无咎”矣。⑥九四重刚而不中，上不在天，下不在田，中不在人，故“或”之，或之者，疑之也。故“无咎”。⑦夫“大人”者，与天地合其德，与日月合其明，与四时合其序，与鬼神合其吉凶。先天而天弗违，后天而奉天时，天且弗违，而况于人乎！况于鬼神乎！⑧“亢”之为言也，知进而不知退，知存而不知亡，知得而不知丧，其唯圣人乎！知进退存亡而不失其正者，其唯圣人乎！⑨</p><h3 id="注释-1" tabindex="-1">注释 <a class="header-anchor" href="#注释-1" aria-label="Permalink to “注释”">​</a></h3><p>①此以人事释《乾》爻辞。下，释“潜”，指初九之阳居下，其位卑贱。舍，此字古人多解；有谓“舍”通“舒”者，然案之《井》卦初六爻“旧井无禽”，《象》曰：“时舍也。”显然《象》解“舍”为弃，由《文言》称“云从龙”，可知龙本应在天为得时，今在田而曰“时舍也”，可知此处亦解“舍”为弃。试：验。穷：极。</p><p>②此以天道释《乾》爻辞。阳气潜藏：初九一阳居下，故象征阳气潜于下而未动。天下文明：九二阳气上升，故天下文彩光明。文明，文彩光明。偕：俱。乾道乃革：《杂卦》：“革，去故也。”九四爻居上卦之始，故“乾道乃革”。位乎天德：阳至九五而处尊位。天德：指九五天位。极：终极。天则：天象法则。</p><p>③此申《乾·彖》意。即释《乾》卦卦辞。性情：一本作“情性”。性，天性。情，是情意。人禀阴阳而生故有性情。《白虎通德论·情性》：“情性者，何谓也？性者，阳之施。情者，阴之化也。人禀阴阳之气而生，故内怀五性六情。”能：而。美利：美善。此指生物。即云行雨施以生物。刚健中正：《乾》六爻皆阳故“刚健”，二五为中，初、三、五以阳居阳得位故曰正。《乾》六爻中九五居中得正，故曰中正。纯粹精：此卦全阳不杂故曰“纯粹精”。色不杂曰纯，米不杂曰粹，米至细曰精。挥：动，散。一本作辉，二者音同义通假。旁：遍。通：通达。《系辞》：“往来不穷谓之通。”六龙：六位之龙。御：驾马使行。云行雨施：指天之功用。云气流行，雨泽布施。平：均匀平和。</p><p>④此释初九爻辞。成德：已成就的道德。弗：不。</p><p>⑤此释九二爻辞。聚：会。辩：一本作辨。二者通，有明辨之义。宽：弘广。</p><p>⑥此释九三爻辞。重刚：九三居内卦乾之终，上与外卦乾之初相接，乾为刚，故曰“重刚”。不中：指九三不处二五之位，爻以二五为中。上不在天，指往上不在九五爻。天，指九五爻。此爻辞为“飞龙在天”。田，指九二爻。此爻辞为“见龙在田”。</p><p>⑦此释九四爻辞。中不在人：九四居卦中间而不处人之正位。中，指居卦之中。人，指人位。卦三、四爻为人位，三与二相比，故三附于地处人之正位。四虽处人位，但元于地而近天，非人所处，故九四“中不在人”。</p><p>⑧此释九五爻辞。大人：此指九五而言，九五有“利见大人”之辞。大人指圣明德备之人。《周易》中有周人五号：帝，天称。王，美称。天子，爵号。大君，兴感行异。大人，圣明德备。序：次序。鬼神：阴阳之气屈伸变化，天时：四时。</p><p>⑨此释上九爻辞。上“圣人”王肃本作“愚人”，案愚人、圣人相对为文，故王肃本极是。唯：通惟，犹是。《文选·甘泉赋》李善注：“惟，是也。”</p><p>坤文言</p><p>坤至柔而动也刚，至静而德方，后得主而有常，含万物而化光。坤道其顺乎，承天而时行。①积善之家必有余庆，积不善之家必有余殃。臣弑其君，子弑其父，非一朝一夕之故，其所由来者渐矣。由辩之不早辩也。《易》曰：“履霜，坚冰至。”盖言顺也。②“直”其正也，“方”其义也。君子敬以直内，义以方外，敬义立而德不孤。“直方大，不习无不利。”则不疑其所行也。③阴虽有美，“含”之以从王事，弗敢成也。地道也，妻道也，臣道也。地道“无成”而代“有终”也。④天地变化，草木蕃，天地闭，贤人隐。《易》曰：“括囊，无咎无誉。”盖言谨也。⑤君子“黄”中通理，正位居体，美在其中，而畅于四支，发于事业，美之至也！⑥阴疑于阳必战，为其嫌于无阳也。故称“龙”焉犹未离其类也，故称“血”焉。夫“玄黄”者，天地之杂也，天玄而地黄。⑦</p><h3 id="注释-2" tabindex="-1">注释 <a class="header-anchor" href="#注释-2" aria-label="Permalink to “注释”">​</a></h3><p>①此释《坤》卦卦辞。至柔：《坤》六爻皆阴，纯阴和顺，故曰“至柔”。德方：先儒多解“德”为德性，但由上文“动也刚”思之，“德”与“动”对文，似以作“得”解为妥。方，方正。古人以圆说明天体运动，以方正说明地之静止，故称“方”。“方”释经文中“贞”。后得主：经文中有“先迷后得主”，其意为：先迷惑后找到主人。传文释为“后得主而有常”。显然与经文之义不同。常，规律，常道。化光：化育广大。古“化”有生义。光，广。</p><p>②此释《坤》初六爻辞“履霜，坚冰至”。原意为：踏霜之时，当知坚冰之日将至。弑：试杀。《白虎通德论·诛伐篇》：“弑者，何谓也？弑者，试也。欲言臣子杀其君父不敢卒，候间司事，可稍稍杀弑之。”辩：即辨。渐：渐进，即由小而大。《坤》初六居下，阴小而始动，不善之积，故曰“渐”。阴为不善。顺：顺从。《春秋繁露·基义篇》引作“逊”。</p><p>③此释《坤》六二爻辞。正：从止一，其义守一以止。六二以阴爻居阴位故为“正”。义：宜。六二居中，故为“义”。内：内心。外：</p><p>④此释《坤》六三爻辞“含章可贞，或从王事，无成有终”。经文原意为：蕴含章美可以守正，跟从大王做事，虽不成功，但有好的结果。含：含藏。六三是以阴居阳位，故为“含章”。阳为章美。</p><p>⑤此释《坤》六四爻辞。蕃：草木茂盛。天地闭：天地不交通。六四居上下卦之间，上下皆坤，故上下不交而闭塞。闭，塞。括囊：束扎口袋。</p><p>⑥此释《坤》六五爻辞“黄裳元吉”。黄中：六五居中，而有中德。古代以土色为黄，土在五行中居中，故黄色即中色，黄有中之义。正位居体：六五以阴居阳之正位。五为阳之正位，六五阴爻为体。支：肢，指四肢。发：见。</p><p>⑦此释《坤》上六爻辞“龙战于野，其血玄黄”。阴：《坤》上六为阴。疑：即凝，有交结、聚合之义。嫌：疑。未离类：《坤》上六虽称龙，但未离开阴类。玄黄：天地之正色，此指阴阳相遇两败俱伤。玄：黑中有赤。</p>',36)])])}const f=p(t,[["render",s]]);export{_ as __pageData,f as default};
